import io
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential
from document_client import get_azure_document_intelligence_config
from document_models import ReceiptExtraction, DocumentField, LineItem

def extract_receipt_fields(payload):
    config = get_azure_document_intelligence_config()
    if not config['endpoint'] or not config['api_key']:
        raise ValueError("Azure Document Intelligence endpoint and API key must be configured.")

    client = DocumentIntelligenceClient(config['endpoint'], AzureKeyCredential(config['api_key']))

    with client:
        poller = client.begin_analyze_document(
            'prebuilt-receipt',
            body=io.BytesIO(payload['document_bytes']),
            content_type=payload['mime_type']
        )
        result = poller.result()

    receipts = []
    for document in result.documents or []:
        fields = document.fields or {}

        def get_field(field_name):
            field_data = fields.get(field_name)
            if field_data:
                return DocumentField(content=field_data.content, confidence=field_data.confidence)
            return None

        items_data = fields.get('Items')
        lines = []
        if items_data and items_data.value_array:
            for item in items_data.value_array:
                item_fields = item.value_object or {}
                lines.append(LineItem(
                    description=get_field('Description') if 'Description' in item_fields else None,
                    quantity=get_field('Quantity') if 'Quantity' in item_fields else None,
                    amount=get_field('Amount') if 'Amount' in item_fields else None,
                ))

        receipts.append(ReceiptExtraction(
            merchant=get_field('MerchantName'),
            tax=get_field('TotalTax'),
            total=get_field('Total'),
            items=lines
        ))
    return {'receipts': [r.__dict__ for r in receipts]}

from openai import OpenAI
from document_client import get_openai_config
from document_models import InvoiceExtraction, ReceiptExtraction, DocumentField
from typing import Union, List

def validate_document_fields(extracted_data: Union[InvoiceExtraction, ReceiptExtraction], required_fields: List[str], min_confidence: float = 0.7) -> dict:
    config = get_openai_config()
    api_key = config.get('api_key')
    if not api_key:
        raise ValueError("OpenAI API key must be configured.")

    client = OpenAI(api_key=api_key)

    validation_results = {
        "is_valid": True,
        "missing_fields": [],
        "low_confidence_fields": [],
        "validation_notes": []
    }

    data_dict = extracted_data.__dict__

    # Check for required fields and confidence scores
    for field_name in required_fields:
        field_value = data_dict.get(field_name)
        if not field_value:
            validation_results["is_valid"] = False
            validation_results["missing_fields"].append(field_name)
        elif isinstance(field_value, DocumentField):
            if field_value.confidence is None or field_value.confidence < min_confidence:
                validation_results["is_valid"] = False
                validation_results["low_confidence_fields"].append({'field': field_name, 'confidence': field_value.confidence})
        elif isinstance(field_value, list): # Handle line items, assuming they are lists of LineItem objects or dicts
            if not field_value:
                validation_results["is_valid"] = False
                validation_results["missing_fields"].append(field_name)
            else:
                # For line items, check if at least one item exists, and optionally check sub-fields
                # This example does a basic check if the list is not empty.
                pass # More complex line item validation can be added here if needed.

    # Use OpenAI to provide general validation notes or identify potential issues beyond simple checks
    try:
        prompt = f"Review the following extracted document data and provide any observations on its completeness or potential inaccuracies, especially regarding missing or low-confidence fields. Focus on the overall quality for structured data extraction. Data: {json.dumps(data_dict)}"
        response = client.chat.completions.create(
            model="gpt-4o-mini", # Using a more recent model
            messages=[
                {"role": "system", "content": "You are a helpful assistant that validates structured document extraction data."},
                {"role": "user", "content": prompt}
            ]
        )
        validation_results["validation_notes"].append(response.choices[0].message.content)
    except Exception as e:
        validation_results["validation_notes"].append(f"Error calling OpenAI for advanced validation: {e}")

    return validation_results

from openai import OpenAI
from document_client import get_openai_config
from document_models import InvoiceExtraction
import json

def summarize_invoice(invoice_data: InvoiceExtraction) -> str:
    config = get_openai_config()
    api_key = config.get('api_key')
    if not api_key:
        raise ValueError("OpenAI API key must be configured.")

    client = OpenAI(api_key=api_key)

    invoice_dict = invoice_data.__dict__
    # Convert DocumentField objects to their content for better summarization
    if invoice_dict.get('vendor') and hasattr(invoice_dict['vendor'], 'content'):
        invoice_dict['vendor'] = invoice_dict['vendor'].content
    if invoice_dict.get('date') and hasattr(invoice_dict['date'], 'content'):
        invoice_dict['date'] = invoice_dict['date'].content
    if invoice_dict.get('total') and hasattr(invoice_dict['total'], 'content'):
        invoice_dict['total'] = invoice_dict['total'].content

    # For line items, extract content for description, quantity, amount
    if 'line_items' in invoice_dict:
        processed_line_items = []
        for item in invoice_dict['line_items']:
            processed_item = {}
            if hasattr(item, 'description') and hasattr(item.description, 'content'):
                processed_item['description'] = item.description.content
            if hasattr(item, 'quantity') and hasattr(item.quantity, 'content'):
                processed_item['quantity'] = item.quantity.content
            if hasattr(item, 'amount') and hasattr(item.amount, 'content'):
                processed_item['amount'] = item.amount.content
            processed_line_items.append(processed_item)
        invoice_dict['line_items'] = processed_line_items

    prompt = f"Summarize the following invoice data in a concise paragraph, highlighting key details like vendor, total amount, date, and a brief overview of line items. Invoice data: {json.dumps(invoice_dict)}"

    try:
        response = client.chat.completions.create(
            model="gpt-4o-mini",
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes invoice data."},
                {"role": "user", "content": prompt}
            ]
        )
        return response.choices[0].message.content
    except Exception as e:
        return f"Error summarizing invoice with OpenAI: {e}"
